function ePrepare(array $t,array $draft,string $body='E draft',string $kind='reply',?string $who=null): array{global $commands,$ref;$who??=$ref;$p=['action'=>'send','payload'=>['ticket_id'=>$t['id'],'kind'=>$kind,'body'=>$body,'version'=>$t['version'],'draft_version'=>$draft['version']]];$r=$commands->command($who,$who===$GLOBALS['client']?'client':'admin','prepare',$p,Id::uuid(),Id::uuid());$p['confirmation']=['id'=>$r['id'],'accepted'=>true];return $p;}
