test('F5-E send transaction failure rolls back message event receipt confirmation and draft clear',function()use($f,$commands,$store,$ref): void{$t=bTicket($f);$d=eDraft($t);$p=ePrepare($t,$d);$before=dCounts($f);$f['db']->execute("CREATE TRIGGER e_message_failure BEFORE INSERT ON support_messages FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Synthetic E failure'");try{raises(PDOException::class,fn()=>$commands->command($ref,'admin','execute',$p,Id::uuid(),Id::uuid()));same($before,dCounts($f));same(null,$f['db']->execute('SELECT used_at FROM support_ui_confirmations WHERE id=?',[$p['confirmation']['id']])->fetchColumn());same($d['id'],$store->view($ref,'admin','draft',['ticket_id'=>$t['id'],'kind'=>'reply'])['draft']['id']);}finally{$f['db']->execute('DROP TRIGGER e_message_failure');}});
