test('F5-E independent 1 4 8 PHP send replays produce one message event completion and cleared draft',function()use($f,$commands,$store,$ref): void{foreach([1,4,8] as $workers){$t=bTicket($f);$draft=eDraft($t);$body=ePrepare($t,$draft);$key=Id::uuid();$children=[];for($i=0;$i<$workers;++$i){$pipes=[];$p=proc_open([PHP_BINARY,__DIR__.'/support-e-child.php'],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,null,bEnvironment($f));if(!is_resource($p)){throw new RuntimeException('Child unavailable');}fwrite($pipes[0],json_encode(['reference'=>$ref,'body'=>$body,'key'=>$key],JSON_THROW_ON_ERROR));fclose($pipes[0]);$children[]=[$p,$pipes];}foreach($children as [$p,$pipes]){$r=json_decode(stream_get_contents($pipes[1]),true,32,JSON_THROW_ON_ERROR);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);same(0,proc_close($p));same('',$err);same(200,$r['status']);same(2,$r['result']['version']);}same(2,(int)$f['db']->execute('SELECT COUNT(*) FROM support_messages WHERE ticket_id=?',[$t['id']])->fetchColumn());same(1,(int)$f['db']->execute("SELECT COUNT(*) FROM support_events WHERE ticket_id=? AND kind='STAFF_REPLY'",[$t['id']])->fetchColumn());same(1,(int)$f['db']->execute("SELECT COUNT(*) FROM support_sla_history h JOIN support_sla_clocks c ON c.id=h.clock_id JOIN support_sla_cycles y ON y.id=c.cycle_id WHERE y.ticket_id=? AND c.metric='FIRST' AND h.kind='COMPLETED'",[$t['id']])->fetchColumn());same(null,$store->view($ref,'admin','draft',['ticket_id'=>$t['id'],'kind'=>'reply'])['draft']);}});
