test('F5-E actual installed 053 upgrade applies only 054 and leaves previous migration rows unchanged',function(): void{$db=isolatedDomainDb();$root=dirname(__DIR__);$dir=$root.'/storage/e-prefix-'.bin2hex(random_bytes(5));mkdir($dir,0700);$files=[];try{foreach(glob($root.'/migrations/*.php') as $p){if(basename($p)<'054'){$copy=$dir.'/'.basename($p);copy($p,$copy);$files[]=$copy;}}same(53,count((new \Hostider\Core\Database\Migrator($db,$dir))->migrate()));$old=$db->execute('SELECT * FROM schema_migrations ORDER BY version')->fetchAll();$m=new \Hostider\Core\Database\Migrator($db,$root.'/migrations');same(['054_support_ui_state.php','055_support_auto_close.php'],$m->migrate());same([],$m->migrate());same($old,$db->execute("SELECT * FROM schema_migrations WHERE version<'054' ORDER BY version")->fetchAll());$m->assertReady();}finally{foreach($files as $p){unlink($p);}rmdir($dir);}});
test('F5-E native HTTP create assign reply SLA incident CSAT report flow remains atomic and scoped',function()use($f): void{$server=new HttpTestServer(dirname(__DIR__),bEnvironment($f),__DIR__.'/commerce-router.php');$a=['cookies'=>[],'csrf'=>''];$c=$a;try{dClientLogin($server,$f['client'],$c);bHttp($server,'/api/v1/admin/identity/bootstrap',$a);same(200,bHttp($server,'/api/v1/admin/identity/login',$a,['email'=>$f['admin']['email'],'password'=>$f['admin']['password']])[0]);same(200,bHttp($server,'/api/v1/admin/identity/mfa',$a,['code'=>$f['admin']['recovery'][3]])[0]);same(200,bHttp($server,'/api/v1/admin/identity/step-up',$a,['password'=>$f['admin']['password'],'code'=>$f['admin']['recovery'][4]])[0]);$create=bHttp($server,'/api/v1/client/support/create',$c,['department_id'=>$f['departments'][0],'subject'=>'E integrated HTTP','body'=>'Synthetic start','priority'=>'NORMAL']);same(200,$create[0]);$t=$create[1]['data'];$confirmed=function(string $area,string $action,array $payload)use($server,&$a): array{$p=['action'=>$action,'payload'=>$payload];$prep=bHttp($server,'/api/v1/admin/'.$area.'/prepare',$a,$p);same(200,$prep[0]);$p['confirmation']=['id'=>$prep[1]['data']['id'],'accepted'=>true];$r=bHttp($server,'/api/v1/admin/'.$area.'/execute',$a,$p);same(200,$r[0]);return $r[1]['data'];};bRoster($f,$f['admin']['user']);$r=$confirmed('support-work','assign',['id'=>$t['id'],'version'=>1,'assignee_id'=>$f['admin']['user']]);same($f['admin']['user'],bWork($f,$t)['assignee_id']);$v=(int)bRow($f,$t)['version'];same(200,bHttp($server,'/api/v1/admin/support-ui/draft-save',$a,['ticket_id'=>$t['id'],'kind'=>'reply','body'=>'Integrated public response','version'=>0,'base_version'=>$v])[0]);$r=$confirmed('support-ui','send',['ticket_id'=>$t['id'],'kind'=>'reply','body'=>'Integrated public response','version'=>$v,'draft_version'=>1]);$i=$confirmed('support-advanced','incident-new',['department_id'=>$f['departments'][0],'version'=>0,'title'=>'Public integrated incident','description'=>'Synthetic public update','private_root'=>'E_INTEGRATED_PRIVATE','affected'=>'Synthetic']);$r=$confirmed('support-advanced','incident-link',['ticket_id'=>$t['id'],'version'=>$r['version'],'incident_id'=>$i['id']]);$r=$confirmed('support-ui','state',['ticket_id'=>$t['id'],'version'=>$r['version'],'status'=>'RESOLVED']);$confirmed('support-advanced','csat-policy',['department_id'=>$f['departments'][0],'version'=>0,'window_seconds'=>600]);same(200,bHttp($server,'/api/v1/client/support-advanced/csat',$c,['ticket_id'=>$t['id'],'ticket_version'=>$r['version'],'version'=>0,'score'=>5,'comment'=>'Synthetic'])[0]);$client=bHttp($server,'/api/v1/client/support-ui/detail?id='.$t['id'],$c);same(200,$client[0]);same(false,str_contains($client[2],'E_INTEGRATED_PRIVATE'));same([$i['id']],array_column($client[1]['data']['incidents'],'id'));$report=bHttp($server,'/api/v1/admin/support-advanced/report?from=2026-01-01T00%3A00%3A00Z&to=2027-01-01T00%3A00%3A00Z&timezone=UTC',$a);same(200,$report[0]);same(1,$report[1]['data']['csat']['count']);same(5,$report[1]['data']['csat']['sum']);same('NOT_AVAILABLE',$report[1]['data']['actual_work_hours']);same(1,(int)$f['db']->execute("SELECT COUNT(*) FROM support_sla_clocks c JOIN support_sla_cycles y ON y.id=c.cycle_id WHERE y.ticket_id=? AND c.metric='FIRST' AND c.status='COMPLETED'",[$t['id']])->fetchColumn());same('RESOLVED',bRow($f,$t)['status']);same(false,$f['config']->mail);}finally{$server->stop();}});
